import json,re,html,hashlib
R=Path(__file__).resolve().parents[2];A=json.loads((R/'scripts/project-sources/axion-case-assets.json').read_text());esc=html.escape
base=(R/'public/work/axion-controllers/index.html').read_text();fonts=re.search(r'<style data-local-fonts>.*?</style>',base).group()
css='''
.ax-case{max-width:1600px;margin:auto;padding:0 4vw}.ax-intro{padding:55px 0}.ax-label,.ax-meta,.ax-fig figcaption,.ax-link,.ax-flow span,.ax-colour small{font:11px/1.55 "IBM Plex Mono",monospace;text-transform:uppercase}.ax-kicker{display:flex;justify-content:space-between;gap:20px}.ax-intro h1{font-size:clamp(60px,10.2vw,160px);line-height:.86;letter-spacing:-.065em;margin:48px 0}.ax-lead{display:grid;grid-template-columns:1.7fr 1fr;gap:8vw}.ax-lead>p{font-size:clamp(23px,2.3vw,36px);line-height:1.18;margin:0}.ax-meta{display:grid;gap:18px}.ax-meta dt{opacity:.55}.ax-meta dd{margin:0}.ax-fig{margin:0;min-width:0}.ax-fig img,.ax-fig video{display:block;width:100%;height:auto}.ax-fig video{object-fit:contain;background:#050b13}.ax-fig figcaption{font-size:10px;opacity:.68;margin:12px 0 0}.ax-chapter{padding:64px 0;border-top:1px solid #bcb9b3}.ax-chapter h2{font-size:clamp(38px,5.3vw,80px);line-height:.98;letter-spacing:-.05em;max-width:1100px;margin:22px 0 28px}.ax-body{font-size:19px;line-height:1.5;max-width:800px;margin:0 0 34px}.ax-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;align-items:start}.ax-trio{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.ax-stack{margin-top:24px}.ax-dark{background:#050b13;color:#f8f8f3;margin:0 -4vw;padding:64px 4vw}.ax-dark .ax-label{color:#d8ff3e}.ax-lockup{display:grid;grid-template-columns:1fr 2.5fr;align-items:center;gap:8%;padding:80px 6%;border:1px solid #33404e}.ax-lockup img{width:100%;height:auto;filter:invert(1)}.ax-analysis{background:#e2dfd8;padding:35px}.ax-analysis img{width:100%;height:auto;max-height:250px;object-fit:contain}.ax-analysis p{font:11px/1.5 "IBM Plex Mono",monospace;text-transform:uppercase;margin:25px 0 0}.ax-clear{position:relative;background:#e2dfd8;padding:12%;min-height:360px;display:grid;place-items:center}.ax-clear svg{display:block;width:100%;height:auto;max-width:520px}.ax-clear img{width:min(280px,65%);height:auto;outline:1px dashed #8b8983;outline-offset:32px}.ax-clear::before,.ax-clear::after{content:"";position:absolute;opacity:.22;background:#111}.ax-clear::before{height:1px;width:84%;left:8%;top:50%}.ax-clear::after{width:1px;height:84%;top:8%;left:50%}.ax-rules{font-size:18px;line-height:1.5;padding:10px 0 0}.ax-rules h3{font-size:28px;letter-spacing:-.03em;margin:0 0 20px}.ax-scale{display:flex;align-items:center;gap:36px;margin-top:35px;min-height:80px}.ax-scale img{height:auto}.ax-palettes{display:grid;grid-template-columns:2fr 1fr 1fr;gap:0;margin:35px 0}.ax-colour{min-height:230px;padding:24px;display:flex;flex-direction:column;justify-content:space-between}.ax-colour b{font-size:27px;letter-spacing:-.03em}.ax-type{font-size:clamp(36px,5vw,75px);line-height:.95;letter-spacing:-.055em;margin:40px 0}.ax-link{display:inline-block;padding:15px 0;border-bottom:1px solid currentColor;text-decoration:none;margin-top:20px}.ax-link:hover{color:#a6532a}.ax-link:focus-visible{outline:2px solid #a6532a;outline-offset:7px}.ax-flow{list-style:none;margin:30px 0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.ax-flow li{border-top:1px solid #838079;padding-top:16px;min-height:80px}.ax-flow b{font-size:22px;letter-spacing:-.025em;display:block;margin-top:10px}.ax-note{font:11px/1.65 "IBM Plex Mono",monospace;opacity:.7;max-width:780px}.ax-next{padding:65px 0}.ax-next a{display:block;font-size:clamp(36px,4vw,65px);letter-spacing:-.04em;margin-top:20px}.ax-trio .ax-fig img{background:#050b13}.ax-screens{background:#050b13;padding:24px}.ax-screens .ax-fig figcaption{color:#f8f8f3}.ax-motion-head{margin:30px 0 20px;font-size:28px;letter-spacing:-.03em}@media(max-width:700px){.ax-intro{padding:35px 0}.ax-kicker{font-size:9px}.ax-intro h1{margin:34px 0}.ax-lead,.ax-pair{grid-template-columns:1fr;gap:26px}.ax-meta{grid-template-columns:1fr 1fr}.ax-trio{grid-template-columns:1fr;gap:28px}.ax-analysis{padding:28px}.ax-analysis img{max-height:200px}.ax-lockup{padding:45px 7%;gap:8%;grid-template-columns:1fr 2.5fr}.ax-palettes{grid-template-columns:1fr}.ax-colour{min-height:150px}.ax-flow{grid-template-columns:repeat(2,1fr)}.ax-chapter,.ax-dark{padding-top:42px;padding-bottom:42px}.ax-body{font-size:17px}.ax-screens{padding:16px}.ax-clear{min-height:320px}}
'''
style='axion-case-'+hashlib.sha256(css.encode()).hexdigest()[:12]+'.css';(R/'public/assets'/style).write_text(css)
def page(it):
 T=lambda a,b:a if it else b;lang='it' if it else 'en';pre='/it' if it else '';path=pre+'/work/axion-controllers/';url='https://filippomantini.com'+path
 def fig(k,alt,cap='',eager=False):
  vs=A[k];v=vs[-1];return f'<figure class="ax-fig"><img src="{v["src"]}" srcset="'+', '.join(f'{x["src"]} {x["width"]}w' for x in vs)+f'" sizes="(max-width:700px) 92vw, 48vw" width="{v["width"]}" height="{v["height"]}" alt="{esc(alt)}" loading="'+('eager' if eager else 'lazy')+'" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'+('<figcaption>'+esc(cap)+'</figcaption>' if cap else '')+'</figure>'
 def video(k,cap):
  v=A[k];return f'<figure class="ax-fig"><video controls loop muted playsinline preload="none" poster="{v["poster"]}" width="{v["width"]}" height="{v["height"]}" aria-label="{esc(cap)}"><source src="{v["src"]}" type="video/mp4"></video><figcaption>{esc(cap)}</figcaption></figure>'
 def chapter(n,h,t,body,dark=False):return f'<section class="ax-chapter'+(' ax-dark' if dark else '')+f'"><span class="ax-label">{n}</span><h2>{h}</h2><p class="ax-body">{t}</p>{body}</section>'
 def grid(*v,cls='ax-pair'):return f'<div class="{cls}">'+''.join(v)+'</div>'
 title=T('Axion Controllers — Identità, sito e configuratore 3D','Axion Controllers — Identity, website and 3D configurator');desc=T('Identità visiva, sistema del logo, sito e-commerce, configuratore 3D e comunicazione di prodotto per Axion Controllers. Un progetto di Filippo Mantini.','Visual identity, logo system, e-commerce website, 3D configurator and product communication for Axion Controllers. A project by Filippo Mantini.')
 intro=f'<section class="ax-intro"><div class="ax-kicker ax-label"><span>FM—004 / AXION CONTROLLERS</span><span>2025—2026 / IDENTITY & DIGITAL</span></div><h1>AXION<br>CONTROLLERS</h1><div class="ax-lead"><p>'+T('Ho lavorato all’identità e all’esperienza digitale di Axion: dal marchio alla presentazione del prodotto, dal sito e-commerce al percorso di configurazione del controller.','I worked on Axion’s identity and digital experience: from the mark to product presentation, from the e-commerce website to the controller configuration journey.')+f'</p><dl class="ax-meta"><div><dt>{T("Ruolo","Role")}</dt><dd>Visual identity / Web design / Digital product</dd></div><div><dt>{T("Ambito","Scope")}</dt><dd>Logo system / E-commerce / 3D / Product image</dd></div><div><dt>{T("Progetto","Project")}</dt><dd>Axion Controllers</dd></div></dl></div></section>'
 body=fig('campaign',T('Campagna Axion con controller su un set blu','Axion campaign with controllers on a blue set'),T('Immagine di campagna / archivio Axion','Campaign image / Axion archive'),True)
 body+=chapter('01 / BRAND IDENTITY',T('UN’IDENTITÀ<br>PER IL CONTROLLO.','AN IDENTITY<br>FOR CONTROL.'),T('Axion realizza controller personalizzati. L’identità deve rendere riconoscibile il brand su un prodotto piccolo e accompagnare scelte tecniche nel sito: logo, gerarchie, colore e immagini lavorano in continuità.','Axion builds custom controllers. The identity needs to identify the brand on a small product and guide technical choices online: the logo, hierarchy, colour and imagery work together.'),'<div class="ax-lockup"><img src="/assets/axion-case/symbol.svg" width="531" height="531" alt="Axion — '+T('simbolo originale','original symbol')+'"><img src="/assets/axion-case/wordmark.svg" width="2096" height="538" alt="Axion — '+T('logotipo originale','original wordmark')+'"></div>',True)
 diagrams=''.join('<div class="ax-analysis"><img src="/assets/axion-case/'+k+'.svg" width="531" height="531" alt="'+esc(alt)+'"><p>'+label+'</p></div>' for k,alt,label in [('diagonals',T('Quattro bracci diagonali del simbolo Axion','Four diagonal arms of the Axion symbol'),T('01 / Struttura diagonale','01 / Diagonal structure')),('directions',T('Quattro elementi direzionali del simbolo Axion','Four directional elements of the Axion symbol'),T('02 / Quattro direzioni','02 / Four directions')),('symbol',T('Simbolo Axion completo','Complete Axion symbol'),T('03 / Il segno completo','03 / The complete mark'))])
 body+=chapter('02 / LOGO SYSTEM',T('IL SEGNO,<br>LETTO NELLA SUA STRUTTURA.','READING<br>THE STRUCTURE OF THE MARK.'),T('Il simbolo combina quattro bracci diagonali e quattro elementi direzionali attorno a un centro vuoto. La lettura richiama l’incrocio degli assi e i comandi del controller. Le tavole isolano le parti del vettoriale originale per mostrare come si ricompongono.','The symbol combines four diagonal arms and four directional elements around an open centre. It evokes intersecting axes and controller inputs. The boards isolate parts of the original vector artwork to show how they come together.'),'<div class="ax-trio">'+diagrams+'</div><div class="ax-stack">'+grid('<div class="ax-clear"><svg viewBox="0 0 700 700" role="img" aria-label="'+T('Area di rispetto proposta: un ottavo della larghezza del simbolo','Proposed clear space: one eighth of the symbol width')+'"><rect x="100" y="100" width="500" height="500" fill="none" stroke="#8b8983" stroke-dasharray="6 6"/><image href="/assets/axion-case/symbol.svg" x="150" y="150" width="400" height="400"/><path d="M100 75H150M100 65V85M150 65V85" stroke="#111" fill="none"/><text x="120" y="55" font-family="monospace" font-size="24">x</text><text x="205" y="660" font-family="monospace" font-size="20">x = W / 8</text></svg></div>','<div class="ax-rules"><h3>'+T('Spazio, contrasto, riduzione.','Space, contrast, reduction.')+'</h3><p>'+T('La regola di impiego proposta riserva almeno un modulo x attorno al marchio, con x pari a un ottavo della larghezza del simbolo. Il segno mantiene la stessa costruzione nelle versioni monocromatiche positiva e negativa.','The proposed usage rule reserves at least one module x around the mark, where x is one eighth of the symbol width. The mark retains the same construction in positive and reversed monochrome versions.')+'</p><div class="ax-scale">'+''.join(f'<img src="/assets/axion-case/symbol.svg" width="{w}" height="{w}" alt="Axion / {w}px">' for w in [64,40,24])+'</div><p class="ax-note">'+T('Prova di riduzione / 64, 40, 24 px','Reduction study / 64, 40, 24 px')+'</p></div>')+'</div>')
 palette='<div class="ax-palettes">'+''.join(f'<div class="ax-colour" style="background:{c};color:{fg}"><b>{n}</b><small>{c}<br>{role}</small></div>' for c,fg,n,role in [('#050B13','#F8F8F3','DEEP NAVY',T('Fondo / struttura','Background / structure')),('#D8FF3E','#050B13','AXION LIME',T('Azione / selezione','Action / selection')),('#F8F8F3','#050B13','OFF WHITE',T('Testo / contrasto','Text / contrast'))])+'</div>'
 body+=chapter('03 / VISUAL LANGUAGE',T('COLORE COME<br>INDICAZIONE.','COLOUR<br>AS A SIGNAL.'),T('Il blu profondo sostiene immagini e interfaccia; il lime identifica azioni e selezioni, mentre il bianco mantiene leggibili testi e dati. Sul sito la famiglia sans serif Inter organizza titoli, descrizioni e informazioni tecniche.','Deep navy supports the imagery and interface; lime identifies actions and selections, while off-white keeps text and data readable. On the website, the Inter sans-serif family organises headings, descriptions and technical information.'),palette+'<p class="ax-type">TAKE OVER.<br>TAKE CONTROL.<br>TAKE AXION.</p>'+fig('website-home',T('Homepage originale del sito Axion Controllers','Original Axion Controllers website homepage'),T('Sito reale / schermata desktop','Live website / desktop capture')))
 body+=chapter('04 / DIGITAL EXPERIENCE',T('DAL PRODOTTO<br>ALLE SCELTE DELL’UTENTE.','FROM THE PRODUCT<br>TO THE USER’S CHOICES.'),T('Il configuratore divide la scelta in sette passaggi: input posteriori, comandi Smart, analogici, scocca, personalizzazione, realizzazione e riepilogo. L’interfaccia rende visibili selezioni e prezzo, poi raccoglie la configurazione in un codice condivisibile.','The configurator divides the choice into seven steps: rear inputs, Smart inputs, sticks, shell, customisation, production and review. The interface displays selections and price, then packages the configuration into a shareable code.'),'<ol class="ax-flow">'+''.join(f'<li><span>{i:02d} / STEP</span><b>{label}</b></li>' for i,label in enumerate(T(['Bottoni posteriori','Smart Input','Analogici TMR','Scocca','Personalizzazione','Realizzazione','Review'],['Rear buttons','Smart Input','TMR sticks','Shell','Customisation','Production','Review']),1))+'</ol><figure class="ax-fig"><img src="/assets/axion-designer-home-cover.webp" width="1920" height="1080" loading="lazy" decoding="async" alt="Axion Designer — '+T('presentazione del configuratore','configurator presentation')+'"><figcaption>AXION DESIGNER / 3D EXPERIENCE</figcaption></figure><div class="ax-screens ax-stack">'+grid(*(fig(k,alt,cap) for k,alt,cap in [('ui-rear',T('Pannello reale di scelta dei bottoni posteriori','Actual rear button selection panel'),'01 / REAR INPUTS'),('ui-tmr',T('Pannello reale di scelta degli analogici TMR','Actual TMR stick selection panel'),'03 / TMR STICKS'),('ui-review',T('Riepilogo reale della configurazione Axion','Actual Axion configuration review'),'07 / BUILD REVIEW')]),cls='ax-trio')+'</div><p class="ax-note ax-stack">'+T('Dettagli dell’interfaccia acquisiti dal sito. La disponibilità e i prezzi visibili appartengono alla schermata documentata.','Interface details captured from the website. Visible availability and prices belong to the documented screen.')+'</p><a class="ax-link" href="https://www.axioncontrollers.it/products/axion-designer-ps5" target="_blank" rel="noopener noreferrer">'+T('Apri il configuratore sul sito Axion ↗','Open the configurator on Axion’s website ↗')+'</a>')
 body+=chapter('05 / PRODUCT IMAGE',T('FORMA, PRESA,<br>DETTAGLIO.','FORM, GRIP,<br>DETAIL.'),T('Le immagini di prodotto mostrano il controller intero e i punti su cui interviene la personalizzazione: comandi posteriori, impugnatura, trigger e finiture. La sequenza alterna viste generali e dettagli ravvicinati.','Product images show the whole controller and the areas affected by customisation: rear inputs, grip, triggers and finishes. The sequence alternates general views with close-up details.'),grid(fig('front',T('Controller Axion nero — vista frontale','Black Axion controller — front view'),'01 / FRONT'),fig('back',T('Controller Axion nero — vista posteriore','Black Axion controller — rear view'),'02 / BACK'))+'<div class="ax-stack">'+grid(fig('rear-detail',T('Dettaglio dei comandi posteriori Axion','Axion rear input detail'),'03 / REAR INPUT'),fig('grip-detail',T('Texture dell’impugnatura Axion','Axion grip texture'),'04 / GRIP'))+'</div><div class="ax-stack">'+grid(fig('top',T('Vista superiore del controller Axion','Axion controller top view'),'05 / TOP'),fig('trigger-detail',T('Dettaglio trigger e bumper Axion','Axion trigger and bumper detail'),'06 / TRIGGERS'))+'</div>')
 body+=chapter('06 / MOVING IMAGE',T('IL PRODOTTO<br>IN MOVIMENTO.','THE PRODUCT<br>IN MOTION.'),T('Quattro brevi studi visivi presentano il retro, i materiali, la postazione di gioco e il modulo TMR. Il movimento cambia punto di vista e rende visibili le caratteristiche del prodotto.','Four short visual studies present the rear, materials, gaming station and TMR module. Movement changes the viewpoint and reveals product features.'),grid(video('motion-back','01 / REAR DETAIL'),video('motion-material','02 / MATERIAL STUDY'))+'<div class="ax-stack">'+grid(video('motion-station','03 / GAMING STATION'),video('motion-tmr','04 / TMR MODULE'))+'</div>')
 body+='<section class="ax-next"><span class="ax-label">'+T('Progetto successivo','Next project')+f'</span><a href="{pre}/work/rebuild-yourself/">REBUILD YOURSELF ↗</a></section>'
 ld={'@context':'https://schema.org','@type':'CreativeWork','name':title,'description':desc,'url':url,'image':'https://filippomantini.com'+A['campaign'][-1]['src'],'creator':{'@type':'Person','name':'Filippo Mantini'},'inLanguage':lang}
 breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://filippomantini.com'+pre+'/'},{'@type':'ListItem','position':2,'name':'Axion Controllers','item':url}]}
 head=f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Filippo Mantini</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{url}"><meta property="og:type" content="article"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="https://filippomantini.com{A["campaign"][-1]["src"]}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="https://filippomantini.com{A["campaign"][-1]["src"]}"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/assets/static/project-5497922a5cc4.css"><link rel="stylesheet" href="/assets/{style}">'+fonts+'<script type="application/ld+json">'+json.dumps(ld,ensure_ascii=False)+'</script><script type="application/ld+json">'+json.dumps(breadcrumb)+'</script></head>'
 nav=f'<body><div class="site-cursor" id="siteCursor" aria-hidden="true"></div><header class="topbar"><a class="name" href="{pre}/">FILIPPO MANTINI</a><nav><a href="{pre}/#work">Work</a><a href="{pre}/#photo">Photo</a><a href="'+('/studio/' if it else '/work/filippo-mantini-studio/')+f'">Studio AI</a><a href="{pre}/about/">About</a><a href="'+('/work/axion-controllers/' if it else '/it/work/axion-controllers/')+'">'+('EN' if it else 'IT')+f'</a></nav><a class="back" href="{pre}/#work">← '+T('Tutti i progetti','Back to work')+'</a></header>'
 target=R/'public'/path.strip('/')/'index.html';target.write_text(head+nav+'<main class="ax-case">'+intro+body+f'</main><footer class="footer"><span>Filippo Mantini © 2026</span><a href="mailto:info@filippomantini.com">info@filippomantini.com</a><a href="{pre}/privacy/">Privacy</a></footer><script src="/assets/static/project-cursor-10bb0092983c.js" defer></script><script src="/assets/static/video-playback-f1c3d61df99e.js" defer></script></body></html>')
for it in [False,True]:page(it)
